/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}

/**
 * Streams the audit-log CSV; requires `activity:export`.
 *
 * Owner D. `activity:export` sits above `activity:read` in `ROLE_MATRIX` —
 * reading the feed in the UI and walking off with the whole audit trail are
 * different privileges.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { exportActivitySchema } from "@/schemas/activity";
import { listActivity } from "@/server/services/activity-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActivityEvent } from "@/types/activity";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "occurredAt",
  "action",
  "actorId",
  "subjectKind",
  "subjectId",
  "projectId",
  "summary",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!can(actor, "activity:export", { kind: "activity", orgId: actor.orgId })) {
      return failure("forbidden", "Exporting the audit log requires an admin.");
    }

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const parsed = exportActivitySchema.safeParse({
      orgId: actor.orgId,
      since: url.searchParams.get("since"),
      until: url.searchParams.get("until"),
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure(
        "validation_failed",
        "since and until must be ISO-8601 timestamps.",
      );
    }

    const page = await listActivity(actor, {
      orgId: parsed.data.orgId,
      since: parsed.data.since,
      until: parsed.data.until,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (parsed.data.format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-activity-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

function toRow(
  event: ActivityEvent,
): Record<string, string | number | boolean | null> {
  return {
    occurredAt: event.occurredAt,
    action: event.action,
    actorId: event.actorId,
    subjectKind: event.subjectKind,
    subjectId: event.subjectId,
    projectId: event.projectId,
    summary: event.summary,
  };
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

