import { updateProject, archiveProject, restoreProject } from './src/server/services/project-service';
import { updateOrganization } from './src/server/services/organization-service';

const cleanup = await useTemporaryDatabase();
const detach = registerActivityListeners();
try {
  const tenant = await createTenant('audit-check', 'growth');
  const other = await createTenant('audit-check-other', 'growth');
  const at = toIsoTimestamp('2024-01-01T00:00:00Z');
  const later = toIsoTimestamp('2024-01-02T00:00:00Z');
  for (let i = 0; i < 225; i++) {
    await record(tenant.org.id, 'issue.status_changed', {
      actorId: tenant.userIds.member, subjectKind: 'issue', subjectId: "'`issue-${i}`,
      projectId: tenant.project.id, summary: '"'Status changed',
      metadata: { from: 'todo', to: 'done' }, occurredAt: i < 150 ? at : later,
    });
  }
  await record(other.org.id, 'issue.status_changed', {
    actorId: other.userIds.member, subjectKind: 'issue', subjectId: 'foreign',
    projectId: other.project.id, summary: 'Foreign', occurredAt: at,
  });
  const input = { orgId: tenant.org.id, since: at, until: later, format: 'json' as const };
  const entries = JSON.parse(await exportActivity(tenant.actors.admin, input));
  assert.equal(entries.length, 225);
  assert.equal(new Set(entries.map((event: { id: string }) => event.id)).size, 225);
  assert(entries.every((event: { orgId: string }) => event.orgId === tenant.org.id));
  assert(entries.slice(0, 75).every((event: { occurredAt: string }) => event.occurredAt === later));
  assert.deepEqual(entries[0].metadata, { from: 'todo', to: 'done' });
  assert.equal(JSON.parse(await exportActivity(tenant.actors.admin, { ...input, until: at })).length, 150);
  assert.equal((await exportActivity(tenant.actors.admin, { ...input, format: 'csv' })).trim().split('\\n').length, 226);
  await assert.rejects(exportActivity(tenant.actors.admin, { ...input, since: later, until: at }));
  await assert.rejects(listActivity(tenant.actors.member, { orgId: tenant.org.id, since: later, until: at, limit: 25 }));

  const issue = await createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id));
  await assignIssue(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, assigneeId: tenant.userIds.admin });
  await changeIssueStatus(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, status: 'todo' });
  await updateIssue(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, title: 'Edited issue' });
  const comment = await createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, body: 'hello', parentId: null, mentionedUserIds: [] });
  await updateComment(tenant.actors.member, { orgId: tenant.org.id, commentId: comment.id, body: 'edited' });
  await deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: comment.id });
  await archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
  await updateProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: tenant.project.id, name: 'Edited project' });
  await archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: tenant.project.id, archiveIssues: false });
  await restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
  await updateOrganization(tenant.actors.admin, { orgId: tenant.org.id, name: 'Edited org' });
  await emit('member.joined', { orgId: tenant.org.id, actorId: tenant.userIds.member, occurredAt: at, memberId: tenant.userIds.member as never, userId: tenant.userIds.member, role: 'member' });
  await emit('member.removed', { orgId: tenant.org.id, actorId: tenant.userIds.admin, occurredAt: at, memberId: tenant.userIds.member as never, userId: tenant.userIds.member });
  await emit('flag.toggled', { orgId: tenant.org.id, actorId: tenant.userIds.admin, occurredAt: at, flag: 'csv_export', enabled: true });
  const actions = ['issue.created', 'issue.assigned', 'issue.updated', 'issue.archived', 'comment.created', 'comment.updated', 'comment.deleted', 'project.updated', 'project.archived', 'project.restored'] as const;
  const page = await listActivity(tenant.actors.member, { orgId: tenant.org.id, projectId: tenant.project.id, action: [...actions], limit: 100 });
  assert.equal(page.items.length, actions.length);
  for (const action of actions) assert.equal(page.items.filter(event => event.action === action).length, 1);
  assert.equal(page.items.find(event => event.action === 'issue.assigned')?.actorId, tenant.userIds.member);
  const scopedStatus = await listActivity(tenant.actors.member, { orgId: tenant.org.id, projectId: tenant.project.id, action: ['issue.status_changed'], limit: 100 });
  assert.equal(scopedStatus.total, 226);
  for (const action of ['organization.updated', 'member.joined', 'member.removed', 'flag.toggled'] as const) {
    const logged = await listActivity(tenant.actors.member, { orgId: tenant.org.id, action: [action], limit: 25 });
    assert.equal(logged.items.length, 1);
  }
  console.log('Audit regression checks passed');
} finally {
  detach();
  cleanup();
}
